const items = $input.all();
const loopItems = $('Loop Over Items').all();

const results = [];

for (let i = 0; i < items.length; i++) {
  const input = items[i].json;
  const loopData = loopItems[i]?.json || loopItems[0]?.json || {};

  const company = loopData.Company || loopData.company || '';
  const company_url = loopData['Website'] || loopData.company_url || loopData.domain || '';
  const url = loopData['Page URL'] || loopData.url || '';

  let reason = 'Unknown';
  const statusCode = input.statusCode || 0;
  const bodyLength = input.body?.length || input.data?.length || 0;
  const bodyLower = (input.body || input.data || '').toLowerCase();

  if (statusCode === 403) reason = 'Forbidden (403)';
  else if (statusCode === 429) reason = 'Rate Limited (429)';
  else if (statusCode === 503) reason = 'Service Unavailable (503)';
  else if (statusCode !== 200) reason = `HTTP Error (${statusCode})`;
  else if (bodyLength < 500) reason = 'Response too short';
  else if (bodyLower.includes('captcha')) reason = 'Captcha detected';
  else if (bodyLower.includes('cf-browser-verification')) reason = 'Cloudflare challenge';

  results.push({
    json: {
      company_name: company,
      company_url: company_url,
      page_url: url,
      statusCode: statusCode,
      reason: reason,
      bodyLength: bodyLength
    }
  });
}

return results;

