// Process AI Output
const items = $input.all();
const setItems = $('Setup Page Parameters').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const input = items[i].json;
  const setData = setItems[i]?.json || setItems[0]?.json || {};

  const companyName = setData.company || '';
  const companyUrl = setData.company_url || '';
  const pageUrl = setData.url || '';

  // Get cleanedText from Format Success
  let fullContent = '';
  try {
    const formatItems = $('Transform HTML to Text').all();
    fullContent = formatItems[i]?.json?.cleanedText || '';
  } catch (e) {}

  let projects = [];

  try {
    let aiOutput = input.output || input.text || input;

    if (typeof aiOutput === 'string') {
      const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        aiOutput = JSON.parse(jsonMatch[0]);
      }
    }

    if (aiOutput.projects && Array.isArray(aiOutput.projects)) {
      projects = aiOutput.projects;
    } else if (aiOutput.agency || aiOutput.brand) {
      projects = [aiOutput];
    }
  } catch (e) {}

  if (projects.length === 0) {
    projects = [{
      agency: null,
      brand: null,
      project_name: null,
      full_credits: null,
      additional_collaborators: null
    }];
  }

  for (const p of projects) {
    results.push({
      json: {
        company_name: companyName,
        company_url: companyUrl,
        page_url: pageUrl,
        agency: p.agency || null,
        brand: p.brand || null,
        project_name: p.project_name || null,
        full_credits: p.full_credits || null,
        additional_collaborators: p.additional_collaborators || null,
        full_content: fullContent
      }
    });
  }
}

return results;

