const items = $input.all();
const loopItems = $('Loop Over Items').all();

const results = [];

for (let i = 0; i < items.length; i++) {
  const input = items[i].json;
  const loopData = loopItems[i]?.json || loopItems[0]?.json || {};

  // Use original sheet field names from Loop Over Items
  const company = loopData.Company || loopData.company || '';
  const company_url = loopData['Website'] || loopData.company_url || loopData.domain || '';
  const url = loopData['Page URL'] || loopData.url || '';

  let html = input.data || input.body || '';
  html = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  html = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  html = html.replace(/<noscript[^>]*>[\s\S]*?<\/noscript>/gi, '');
  html = html.replace(/<!--[\s\S]*?-->/g, '');
  let text = html.replace(/<[^>]+>/g, ' ');
  text = text.replace(/\s+/g, ' ').trim();

  const maxLength = 8000;
  if (text.length > maxLength) {
    text = text.substring(0, maxLength) + '... [truncated]';
  }

  results.push({
    json: {
      company: company,
      company_url: company_url,
      url: url,
      statusCode: input.statusCode,
      cleanedText: text,
      textLength: text.length
    }
  });
}

return results;

